  1567  ESPEAK_API const espeak_VOICE **espeak_ListVoices(espeak_VOICE *voice_spec)
  1568  {
  1569          char path_voices[sizeof(path_home)+12];
  1570
  1571          int ix;
  1572          int j;
  1573          espeak_VOICE *v;
  1574          static espeak_VOICE **voices = NULL;
  1575
  1576          // free previous voice list data
  1577          FreeVoiceList();
  1578
  1579          sprintf(path_voices, "%s%cvoices", path_home, PATHSEP);
  1580          GetVoices(path_voices, strlen(path_voices)+1, 0);
  1581
  1582          sprintf(path_voices, "%s%clang", path_home, PATHSEP);
  1583          GetVoices(path_voices, strlen(path_voices)+1, 1);
  1584
  1585          voices_list[n_voices_list] = NULL; // voices list terminator
  1586          espeak_VOICE **new_voices = (espeak_VOICE **)realloc(voices, sizeof(espeak_VOICE *)*(n_voices_list+1));
  1587          if (new_voices == NULL)
  1588                  return (const espeak_VOICE **)voices;
  1589          voices = new_voices;
  1590
  1591          // sort the voices list
  1592          qsort(voices_list, n_voices_list, sizeof(espeak_VOICE *),
  1593                (int(__cdecl *)(const void *, const void *))VoiceNameSorter);
  1594
  1595          if (voice_spec) {
  1596                  // select the voices which match the voice_spec, and sort them by preference
  1597                  SetVoiceScores(voice_spec, voices, 1);
  1598          } else {
  1599                  // list all: omit variant and mbrola voices
  1600                  j = 0;
  1601                  for (ix = 0; (v = voices_list[ix]) != NULL; ix++) {
  1602                          if ((v->languages[0] != 0) && (strcmp(&v->languages[1], "variant") != 0)
  1603                              && (memcmp(v->identifier, "mb/", 3) != 0))
  1604                                  voices[j++] = v;
  1605                  }
  1606                  voices[j] = NULL;
  1607          }
  1608          return (const espeak_VOICE **)voices;
  1609  }
